<script lang="ts">
 import Button from './ui/Button.svelte'; import { invalidateAll } from '$app/navigation';
 let { hasEvents=false }: { hasEvents?: boolean }=$props();
 let input: HTMLInputElement; let busy=$state(false); let message=$state(''); let error=$state(false);
 async function request(url:string, body?:FormData){busy=true; message=''; error=false; try{const response=await fetch(url,{method:'POST',body}); const result=await response.json(); if(!response.ok) throw new Error(result.error||'Import failed'); const count=result.events?.length??result.eventCount??0; message=`${count} events imported${result.run ? ' and reconciled' : ''}.`; await invalidateAll();}catch(e){error=true;message=e instanceof Error?e.message:'Import failed';}finally{busy=false}}
 function upload(files:FileList|null){if(!files?.length)return; const body=new FormData(); for(const file of files)body.append('files',file); request('/api/import',body)}
</script>
<section aria-labelledby="import-title"><div style="display:flex;justify-content:space-between;align-items:end;margin-bottom:12px"><div><p class="eyebrow">Start here</p><h2 id="import-title" class="section-title" style="margin:4px 0 0">Import activity</h2></div>{#if hasEvents}<span class="mono" style="font-size:12px;color:#68705f">Data ready</span>{/if}</div><div class="card"><div class="card-body"><div class="upload" role="button" tabindex="0" onkeydown={(e)=>e.key==='Enter'&&input.click()} onclick={()=>input.click()}><div class="upload-copy"><strong>{busy?'Working…':'Upload processor and bank files'}</strong><span>Stripe, Gumroad, Dodo, or bank · CSV and JSON</span></div><Button disabled={busy}>Choose files</Button><input bind:this={input} hidden type="file" multiple accept=".csv,.json,text/csv,application/json" onchange={(e)=>upload(e.currentTarget.files)}/></div>{#if message}<p class:error class="status">{message}</p>{/if}</div><footer style="padding:12px 20px;border-top:1px solid #e2e6dc;display:flex;justify-content:space-between;gap:10px"><Button variant="ghost" disabled={busy} onclick={()=>request('/api/sample')}>{busy?'Loading and reconciling…':'Load Acme example'}</Button><Button disabled={!hasEvents||busy} onclick={()=>request('/api/reconcile')}>Run reconciliation</Button></footer></div></section>
